def can_jump_brute(nums):
    n = len(nums)

    def helper(pos):
        if pos >= n - 1:
            return True
        for jump in range(1, nums[pos] + 1):               # try every possible jump length
            if helper(pos + jump):
                return True
        return False

    return helper(0)

