public class Main {
    static boolean canJump(int[] nums) {
        int reach = 0;
        for (int i = 0; i < nums.length; i++) {
            if (i > reach) return false;                   // this index is unreachable
            reach = Math.max(reach, i + nums[i]);             // extend the farthest reach
        }
        return true;
    }
}

